import { useEffect, useState } from 'react'
import { useNavigate, useSearchParams } from 'react-router-dom'
import { useCompleteAssessment } from '@/api'
import type { AssessmentResult as Result, ApiError } from '@/api/types'
import { Badge, Button, Card, CardContent } from '@/design/components'

const labels:Record<string,string>={backend:'Backend-разработка',frontend:'Frontend-разработка',mobile:'Мобильная разработка',devops:'DevOps / SRE','data-eng':'Data Engineering',ml:'ML / AI',qa:'QA / тестирование',infosec:'Информационная безопасность',analytics:'Аналитика / BI',embedded:'Embedded-разработка',intern:'Intern',junior:'Junior',middle:'Middle',senior:'Senior',lead:'Lead'}
const human=(value:string|null|undefined)=>value?labels[value]||value.charAt(0).toUpperCase()+value.slice(1):'—'
const errorText=(error:unknown)=>{const e=error as Partial<ApiError>;if(e.status===409)return 'Тест ещё не завершён. Ответьте на оставшиеся задания и повторите.';return e.detail||e.title||(error instanceof Error?error.message:'Не удалось получить результат')}

export default function AssessmentResult(){const navigate=useNavigate();const[params]=useSearchParams();const sessionId=params.get('sessionId');const complete=useCompleteAssessment();const[result,setResult]=useState<Result|null>(null)
useEffect(()=>{if(sessionId&&!result&&!complete.isPending&&!complete.isError)complete.mutate(sessionId,{onSuccess:setResult})},[sessionId,result])
if(!sessionId)return <main className="min-h-screen grid place-items-center"><Card><CardContent className="p-8">Не указан идентификатор сессии.<Button className="mt-4" onClick={()=>navigate('/candidate/dashboard')}>В кабинет</Button></CardContent></Card></main>
if(complete.isError)return <main className="min-h-screen grid place-items-center bg-gray-50"><Card className="max-w-lg"><CardContent className="p-8"><h1 className="text-xl font-bold">Результат пока недоступен</h1><p className="mt-3 text-gray-700">{errorText(complete.error)}</p><Button className="mt-5" onClick={()=>navigate(-1)}>Вернуться к тесту</Button></CardContent></Card></main>
if(!result)return <div className="min-h-screen grid place-items-center bg-gray-50"><div className="text-center"><div className="animate-spin w-12 h-12 border-4 border-primary-accent border-t-transparent rounded-full mx-auto mb-4"/><p>Обрабатываем результаты…</p></div></div>
const category=result.category?`${human(result.category.specialization)} · ${human(result.category.grade)}`:'Нет данных';const probabilities=Object.entries(result.grade_probabilities||{})
return <main className="min-h-screen bg-gray-50 py-8"><div className="max-w-3xl mx-auto px-4 space-y-6"><Card><CardContent className="p-8 text-center"><h1 className="text-3xl font-bold">Результат готов</h1><Badge className="mt-4" variant={result.is_confirmed?'confirmed':'preliminary'}>{result.is_confirmed?'Грейд подтверждён':'Категория предварительная'}</Badge><div className="grid sm:grid-cols-3 gap-4 text-left mt-8"><div><p className="text-sm text-gray-500">Категория</p><p className="text-xl font-bold">{category}</p></div><div><p className="text-sm text-gray-500">Оценка способности θ</p><p className="text-xl font-bold">{result.final_theta==null?'Нет данных':result.final_theta.toFixed(2)}</p></div><div><p className="text-sm text-gray-500">Стандартная ошибка SE</p><p className="text-xl font-bold">{result.final_se==null?'Нет данных':result.final_se.toFixed(2)}</p></div></div></CardContent></Card>
{result.borderline&&<Card className="border-yellow-300"><CardContent className="p-6"><h2 className="font-bold">Пограничный результат</h2><p className="text-gray-700 mt-2">Точности измерения недостаточно для уверенного решения. Подтверждённый ранее грейд не понижается.</p></CardContent></Card>}
<Card><CardContent className="p-6"><h2 className="text-xl font-bold">Как получен результат</h2><p className="mt-3 text-gray-700">{result.reason||'Сервер не передал текстовое объяснение.'}</p>{probabilities.length>0&&<div className="mt-5"><h3 className="font-semibold">Вероятности по грейдам</h3><div className="space-y-2 mt-2">{probabilities.map(([grade,p])=><div key={grade} className="flex justify-between border-b py-2"><span>{human(grade)}</span><span>{(p*100).toFixed(1)}%</span></div>)}</div></div>}</CardContent></Card>
{result.offered_lower_grade&&<Card className="border-purple-300"><CardContent className="p-6"><h2 className="font-bold">Можно подтвердить грейд ниже</h2><p className="mt-2">Система предлагает пройти тест на уровень {human(result.offered_lower_grade)}. Это предложение, а не принудительное понижение.</p><Button className="mt-4" onClick={()=>navigate('/candidate/onboarding/grade')}>Выбрать тест</Button></CardContent></Card>}
<div className="flex gap-3"><Button className="flex-1" onClick={()=>navigate('/candidate/dashboard')}>Перейти в кабинет</Button><Button variant="ghost" onClick={()=>navigate('/candidate/invitations')}>Приглашения</Button></div></div></main>}
